# setdefault inserts only when the key is missing
groups = {}
groups.setdefault("admins", []).append("ada")
print(groups)  # {'admins': ['ada']}

# Sets hold unique values and support algebra
a = {1, 2, 3, 4}
b = {3, 4, 5}

print(a | b)  # {1, 2, 3, 4, 5}
print(a & b)  # {3, 4}
print(a - b)  # {1, 2}
print(a ^ b)  # {1, 2, 5}

# Empty braces make a dict, so use set() for an empty set
