# for walks any iterable; range is lazy
for i in range(3):
    print(i)  # 0 1 2

# break stops the loop, continue skips one iteration
for n in [1, 2, 3, 4]:
    if n == 2:
        continue
    if n == 4:
        break
    print(n)  # 1 3

# while checks the condition before each pass
attempts = 0
while attempts < 2:
    attempts += 1
print(attempts)  # 2

