class Account:
    """A small bank account."""

    bank = "Example Bank"  # class attribute shared by instances

    def __init__(self, owner: str, balance: float = 0.0) -> None:
        self.owner = owner
        self.balance = balance

    def deposit(self, amount: float) -> None:
        if amount <= 0:
            raise ValueError("amount must be positive")
        self.balance += amount

    def __repr__(self) -> str:
        return f"Account({self.owner!r}, {self.balance})"


account = Account("Ada")
account.deposit(50)
print(account)       # Account('Ada', 50.0)
print(account.bank)  # Example Bank

class Savings(Account):
    def __init__(self, owner: str, rate: float) -> None:
        super().__init__(owner)
        self.rate = rate

    @property
    def projected(self) -> float:
        """Balance after one year of simple interest."""
        return self.balance * (1 + self.rate)


savings = Savings("Grace", 0.05)
savings.deposit(200)
print(savings.projected)             # 210.0
print(isinstance(savings, Account))  # True

