def greet(name: str, times: int = 1) -> str:
    return (f"Hello, {name}! " * times).strip()

print(greet("Ada", 2))  # Hello, Ada! Hello, Ada!

from collections.abc import Iterable, Sequence

# Built-in generics: list[int], dict[str, float], set[str]
def total(values: Sequence[float]) -> float:
    return sum(values)

def names(items: Iterable[dict[str, str]]) -> list[str]:
    return [item["name"] for item in items]

print(total([1.5, 2.5]))  # 4.0
print(names([{"name": "Ada"}, {"name": "Alan"}]))  # ['Ada', 'Alan']

from typing import TypedDict


class User(TypedDict):
    name: str
    email: str
    age: int


def find_user(users: list[User], name: str) -> User | None:
    for user in users:
        if user["name"] == name:
            return user
    return None


ada: User = {"name": "Ada", "email": "ada@example.com", "age": 36}
print(find_user([ada], "Ada"))

